-- ==========================================================================
-- Security (was migration 0001)
-- ==========================================================================
-- Selah database security layer: grants, row-level security, append-only
-- history and workflow guards.
--
-- This is the BACKSTOP, not the main check. The main check is authorize() in
-- src/authz. RLS guarantees tenant, project and visibility-label isolation
-- even if app code forgets a check. Finer rules (action owners see only their
-- actions, per-user document shares, which role may move which status) live in
-- authorize().
--
-- Roles (created by db/init/01-roles.sh as superuser):
--   selah_owner  owns the schema, runs migrations. Never used by the app.
--   selah_app    the web app's runtime role. Subject to every policy below.
--   selah_auth   Better Auth's role. Only the auth tables.
--
-- The app sets the caller per transaction with
--   SELECT set_config('selah.user_id', '<uuid>', true)
-- and everything else (org, role, projects) is derived here from tables,
-- so a request can never claim a role it does not have.

-- ------------------------------------------------------------ helpers
CREATE FUNCTION app_uid() RETURNS uuid
LANGUAGE sql STABLE AS $$
  SELECT nullif(current_setting('selah.user_id', true), '')::uuid
$$;
--> statement-breakpoint
CREATE FUNCTION app_org() RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT m.org_id FROM org_memberships m
  JOIN organizations o ON o.id = m.org_id
  WHERE m.user_id = app_uid() AND m.active AND o.status = 'active'
$$;
--> statement-breakpoint
CREATE FUNCTION app_role() RETURNS role
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT m.role FROM org_memberships m
  JOIN organizations o ON o.id = m.org_id
  WHERE m.user_id = app_uid() AND m.active AND o.status = 'active'
$$;
--> statement-breakpoint
CREATE FUNCTION app_org_kind() RETURNS org_kind
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT o.kind FROM org_memberships m
  JOIN organizations o ON o.id = m.org_id
  WHERE m.user_id = app_uid() AND m.active AND o.status = 'active'
$$;
--> statement-breakpoint
CREATE FUNCTION app_user_org(target uuid) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT org_id FROM org_memberships WHERE user_id = target
$$;
--> statement-breakpoint
-- The project check from the spec: organization + role + membership.
CREATE FUNCTION app_is_assigned_to_client(client uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM client_assignments ca WHERE ca.client_org_id = client AND ca.user_id = app_uid())
$$;
--> statement-breakpoint
-- The project check from the spec: organization + role + membership or
-- assignment. Internal projects (org_id = the firm) are firm-only.
CREATE OR REPLACE FUNCTION app_can_see_project(eid uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM projects e
    WHERE e.id = eid AND (
      (app_role() = 'firm_admin' AND e.firm_org_id = app_org())
      OR (app_role() = 'consultant' AND e.firm_org_id = app_org() AND (
            EXISTS (SELECT 1 FROM project_members em WHERE em.project_id = eid AND em.user_id = app_uid())
            OR (e.kind = 'client' AND app_is_client_lead(e.org_id))))
      OR (app_role() = 'client_admin' AND e.kind = 'client' AND e.org_id = app_org())
      OR (app_role() IN ('client_manager', 'action_owner') AND e.kind = 'client' AND e.org_id = app_org()
          AND EXISTS (SELECT 1 FROM project_members em WHERE em.project_id = eid AND em.user_id = app_uid()))
    )
  )
$$;
--> statement-breakpoint
CREATE FUNCTION app_can_see_org(oid uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT oid = app_org()
    OR (app_role() = 'firm_admin' AND EXISTS (SELECT 1 FROM organizations o WHERE o.id = oid AND o.kind = 'client'))
    OR (app_role() = 'consultant' AND app_is_assigned_to_client(oid))
    OR EXISTS (
      SELECT 1 FROM projects e
      WHERE (e.org_id = oid OR e.firm_org_id = oid) AND app_can_see_project(e.id)
    )
$$;
--> statement-breakpoint
CREATE FUNCTION app_can_see_user(target uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT target = app_uid()
    OR (app_role() <> 'action_owner' AND app_user_org(target) = app_org())
    OR EXISTS (
      SELECT 1 FROM project_members em
      WHERE em.user_id = target AND app_can_see_project(em.project_id)
    )
    OR (app_org_kind() = 'firm' AND app_can_see_org(app_user_org(target)))
    -- Client users can see the consultants assigned to their organization.
    OR (app_org_kind() = 'client' AND EXISTS (
      SELECT 1 FROM client_assignments ca WHERE ca.user_id = target AND ca.client_org_id = app_org()
    ))
$$;
--> statement-breakpoint
-- Visibility labels. owner is the row's creator (used for user_private).
CREATE FUNCTION app_label_ok(vis visibility, row_org uuid, owner uuid) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT CASE vis
    WHEN 'shared' THEN true
    WHEN 'firm_private' THEN app_org_kind() = 'firm'
    WHEN 'client_private' THEN app_org_kind() = 'client' AND row_org = app_org()
    WHEN 'user_private' THEN owner IS NOT NULL AND owner = app_uid()
    ELSE false
  END
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app_org(), app_role(), app_org_kind(), app_user_org(uuid), app_is_assigned_to_client(uuid), app_can_see_project(uuid),
  app_can_see_org(uuid), app_can_see_user(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_uid(), app_org(), app_role(), app_org_kind(), app_user_org(uuid), app_is_assigned_to_client(uuid),
  app_can_see_project(uuid), app_can_see_org(uuid), app_can_see_user(uuid),
  app_label_ok(visibility, uuid, uuid) TO selah_app;
--> statement-breakpoint
-- ------------------------------------------------------------- grants
-- Deny by default: a table added later has no grants and no policies until a
-- migration adds them, so the app role cannot read it.
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
--> statement-breakpoint
GRANT USAGE ON SCHEMA public TO selah_app, selah_auth;
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "user", session, account, verification, two_factor TO selah_auth;
--> statement-breakpoint
GRANT SELECT (id, name, email, image) ON "user" TO selah_app;
