-- Append-only tables stay append-only for the app. Only the purge job,
-- running as the schema owner with selah.purge set, may blank their text.
CREATE OR REPLACE FUNCTION forbid_change() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND current_setting('selah.purge', true) = 'on' AND current_user NOT IN ('selah_app', 'selah_auth') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege';
END $$;
--> statement-breakpoint
CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON progress_updates FOR EACH ROW EXECUTE FUNCTION forbid_change();
--> statement-breakpoint
CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON evidence_submissions FOR EACH ROW EXECUTE FUNCTION forbid_change();
--> statement-breakpoint
CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON reviews FOR EACH ROW EXECUTE FUNCTION forbid_change();
--> statement-breakpoint
CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON activity_events FOR EACH ROW EXECUTE FUNCTION forbid_change();
--> statement-breakpoint
CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION forbid_change();
--> statement-breakpoint
-- firm roles only in the firm org, client roles only in client orgs.
CREATE FUNCTION check_membership_role() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE k org_kind;
BEGIN
  SELECT kind INTO k FROM organizations WHERE id = NEW.org_id;
  IF (k = 'firm') <> (NEW.role IN ('firm_admin', 'consultant')) THEN
    RAISE EXCEPTION 'role % does not belong in a % organization', NEW.role, k USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER membership_role BEFORE INSERT OR UPDATE ON org_memberships FOR EACH ROW EXECUTE FUNCTION check_membership_role();
--> statement-breakpoint
-- Projects always pair one firm org with one client org.
CREATE FUNCTION check_project_orgs() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  IF (SELECT kind FROM organizations WHERE id = NEW.firm_org_id) <> 'firm' THEN
    RAISE EXCEPTION 'firm_org_id must be the firm' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.kind = 'internal' AND NEW.org_id <> NEW.firm_org_id THEN
    RAISE EXCEPTION 'an internal project belongs to the firm itself' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.kind = 'client' AND (SELECT kind FROM organizations WHERE id = NEW.org_id) <> 'client' THEN
    RAISE EXCEPTION 'a client project must belong to a client org' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER project_orgs BEFORE INSERT OR UPDATE ON projects FOR EACH ROW EXECUTE FUNCTION check_project_orgs();
--> statement-breakpoint
-- Which status moves exist (who may make them is checked in authz/workflow.ts).
-- Verified Complete additionally needs an 'accept' review as the latest review.
CREATE OR REPLACE FUNCTION check_action_transition() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  is_client boolean := app_uid() IS NOT NULL AND app_org_kind() IS DISTINCT FROM 'firm';
  -- What a client may change. Everything else, including columns added
  -- later, is the firm's.
  client_cols text[] := ARRAY['status', 'owner_user_id', 'blocked_reason', 'updated_at'];
BEGIN
  -- Client users move their actions and (managers, admins) assign owners;
  -- the plan itself is the firm's. Jobs and migrations (no user) are not limited.
  IF is_client AND (
    (to_jsonb(NEW) - client_cols) <> (to_jsonb(OLD) - client_cols)
    OR (NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id AND app_role() NOT IN ('client_admin', 'client_manager'))
  ) THEN
    RAISE EXCEPTION 'clients can only move an action through its workflow' USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW.updated_at := now();

  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;
  IF (OLD.status, NEW.status) NOT IN (
    ('draft', 'assigned'),
    ('assigned', 'in_progress'),
    ('in_progress', 'blocked'),
    ('blocked', 'in_progress'),
    ('in_progress', 'awaiting_review'),
    ('awaiting_review', 'verified_complete'),
    ('awaiting_review', 'revision_requested'),
    ('revision_requested', 'in_progress'),
    ('assigned', 'closed'), ('in_progress', 'closed'), ('blocked', 'closed'),
    ('awaiting_review', 'closed'), ('revision_requested', 'closed'),
    ('verified_complete', 'in_progress'), ('closed', 'in_progress')
  ) THEN
    RAISE EXCEPTION 'invalid action status change % -> %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;

  -- Releasing, reviewing, closing and reopening are the firm's.
  IF is_client AND (OLD.status IN ('draft', 'awaiting_review') OR NEW.status = 'closed' OR OLD.status IN ('verified_complete', 'closed')) THEN
    RAISE EXCEPTION 'only the firm can release, review, close or reopen an action' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Transaction time, like reviews.created_at, so a review written in the
  -- same transaction as the move still belongs to this round.
  IF NEW.status = 'awaiting_review' THEN
    NEW.awaiting_review_at := now();
  END IF;

  IF NEW.status = 'verified_complete' THEN
    -- The accept must review this round: an older accept (before a reopen or
    -- a resubmission) does not count.
    IF COALESCE((
      SELECT r.outcome FROM reviews r
      WHERE r.action_id = NEW.id AND r.created_at >= COALESCE(OLD.awaiting_review_at, '-infinity')
      ORDER BY r.created_at DESC, r.id DESC LIMIT 1
    ), 'reject') <> 'accept' THEN
      RAISE EXCEPTION 'verified_complete needs an accept review of this round' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM evidence_requests er WHERE er.action_id = NEW.id AND er.status NOT IN ('accepted', 'waived')) THEN
      RAISE EXCEPTION 'every evidence request must be accepted or waived first' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.status = 'closed' THEN
    -- Signed since the action was last reopened, by someone who still holds
    -- a client admin or manager role.
    IF NEW.closure_outcome = 'risk_accepted' AND NOT EXISTS (
      SELECT 1 FROM risk_acceptances ra
      JOIN org_memberships m ON m.user_id = ra.accepted_by AND m.org_id = NEW.org_id AND m.active
        AND m.role IN ('client_admin', 'client_manager')
      WHERE ra.action_id = NEW.id AND ra.created_at >= COALESCE(OLD.reopened_at, '-infinity')
    ) THEN
      RAISE EXCEPTION 'risk acceptance needs a signed statement from the client' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.closure_outcome = 'superseded' AND NOT EXISTS (
      SELECT 1 FROM actions a WHERE a.id = NEW.superseded_by AND a.project_id = NEW.project_id
    ) THEN
      RAISE EXCEPTION 'a superseding action must be in the same project' USING ERRCODE = 'check_violation';
    END IF;
    NEW.closed_at := now();
    NEW.closed_by := COALESCE(app_uid(), NEW.closed_by);
  END IF;

  -- Reopening clears the closure; the history stays in activity_events.
  IF OLD.status IN ('verified_complete', 'closed') THEN
    NEW.closure_outcome := NULL;
    NEW.closure_note := NULL;
    NEW.closed_by := NULL;
    NEW.closed_at := NULL;
    NEW.superseded_by := NULL;
    NEW.reopened_at := now();
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER action_transition BEFORE UPDATE ON actions FOR EACH ROW EXECUTE FUNCTION check_action_transition();
--> statement-breakpoint
-- Pull a document's chunks out of the AI index the moment it is unshared,
-- relabelled, archived, deleted or has its AI flag turned off.
CREATE FUNCTION drop_document_chunks() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM ai_chunks WHERE source_type = 'document' AND source_id = OLD.id;
    RETURN OLD;
  END IF;
  IF NOT NEW.ai_indexable OR NEW.visibility <> OLD.visibility OR NEW.state = 'archived' THEN
    DELETE FROM ai_chunks WHERE source_type = 'document' AND source_id = NEW.id;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER document_chunks AFTER UPDATE OF ai_indexable, visibility, state OR DELETE ON documents
  FOR EACH ROW EXECUTE FUNCTION drop_document_chunks();
--> statement-breakpoint

-- ==========================================================================
-- Staffing (was migration 0003)
-- ==========================================================================
-- Staffing model (decided 2026-10-20):
--   * only the firm admin adds clients and names each client's lead consultant
--   * the lead adds or removes consultants on that client
--   * consultants see a directory of client names and may ask to join;
--     the admin or the client's lead decides
--   * any firm member may create an internal project and becomes its lead
--   * on internal projects firm staff do the work; nobody reviews their own

CREATE FUNCTION app_is_client_lead(client uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM client_assignments ca WHERE ca.client_org_id = client AND ca.user_id = app_uid() AND ca.is_lead
  )
$$;
--> statement-breakpoint
CREATE FUNCTION app_is_project_lead(pid uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM project_members pm WHERE pm.project_id = pid AND pm.user_id = app_uid() AND pm.is_lead)
$$;
--> statement-breakpoint
CREATE FUNCTION app_project_kind(pid uuid) RETURNS project_kind
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT kind FROM projects WHERE id = pid
$$;
--> statement-breakpoint
CREATE FUNCTION app_is_active_client(oid uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM organizations o WHERE o.id = oid AND o.kind = 'client' AND o.status = 'active')
