     OR NOT EXISTS (SELECT 1 FROM kpis k WHERE k.id = NEW.kpi_id AND k.project_id = NEW.project_id) THEN
    RAISE EXCEPTION 'the recommendation and the KPI must be in the same project' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
