-- ----------------------------------------------------------- suggestions

-- Up to five consultants for one inquiry, for its firm's admins. Each row
-- says why it is there: the inquiry's services they cover, whether they
-- know its sector and speak its language, whether they are taking new
-- clients, and how many active clients they already have. Consultants who
-- cover none of the services are left out, so an empty list means nobody
-- fits. The order puts available people with the closest match and the
-- lightest load first.
CREATE FUNCTION app_suggest_leads(iid uuid)
RETURNS TABLE (user_id uuid, name text, matched_services text[], sector_match boolean, speaks_language boolean,
               accepting_new_clients boolean, active_clients integer)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
#variable_conflict use_column
DECLARE
  inq inquiries%ROWTYPE;
BEGIN
  SELECT * INTO inq FROM inquiries i WHERE i.id = iid;
  IF NOT FOUND OR inq.firm_org_id IS DISTINCT FROM app_org() OR app_role() IS DISTINCT FROM 'firm_admin' THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT COALESCE((SELECT s.suggestions_enabled FROM firm_settings s WHERE s.org_id = inq.firm_org_id), true) THEN
    RETURN;
  END IF;
  RETURN QUERY
  SELECT p.user_id, u.name,
         array_agg(sa.code ORDER BY sa.sort_order, sa.code),
         EXISTS (SELECT 1 FROM consultant_sectors cs WHERE cs.user_id = p.user_id AND cs.sector_id = inq.sector_id),
         inq.preferred_language = ANY (p.languages),
         p.accepting_new_clients,
         (SELECT count(*)::integer FROM client_assignments ca JOIN organizations o ON o.id = ca.client_org_id
           WHERE ca.user_id = p.user_id AND o.status = 'active')
  FROM consultant_profiles p
  JOIN "user" u ON u.id = p.user_id
  JOIN org_memberships m ON m.user_id = p.user_id AND m.org_id = p.firm_org_id AND m.active AND m.role = 'consultant'
  JOIN consultant_service_areas csa ON csa.user_id = p.user_id
  JOIN inquiry_services isv ON isv.service_area_id = csa.service_area_id AND isv.inquiry_id = inq.id
  JOIN service_areas sa ON sa.id = csa.service_area_id
  WHERE p.firm_org_id = inq.firm_org_id
  GROUP BY p.user_id, u.name, p.languages, p.accepting_new_clients
  ORDER BY 6 DESC, cardinality(array_agg(sa.code)) DESC, 4 DESC, 5 DESC, 7 ASC, 2 ASC
  LIMIT 5;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app_suggest_leads(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_suggest_leads(uuid) TO selah_app;
--> statement-breakpoint

-- ==========================================================================
-- Accounts (was migration 0021)
-- ==========================================================================
-- Accounts and identity (2026-10-20, research section 10).
--
-- People sign in with their own address; Selah never issues mailboxes.
-- Addresses are unique whatever their case (user_email_lower_uq) and
-- must sit on the organisation's email domains when it has set them. Admins
-- invite people (the link goes to the invited address only), change their
-- address (confirmed from the new one), switch accounts off with a reason
-- (their sessions end at once) and, every access_review_days, confirm who
-- still works there. Contacts without a login are firm-only. A PDPL erasure
-- clears a person's details but keeps every id, so the history still holds.

-- ------------------------------------------------------- email domains

-- The domain list is lowercase, without "@", and never empty (null means any).
CREATE FUNCTION normalise_email_domains() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_temp AS $$
DECLARE d text;
BEGIN
  IF NEW.allowed_email_domains IS NOT NULL THEN
    NEW.allowed_email_domains := ARRAY(
      SELECT DISTINCT lower(ltrim(trim(x), '@')) FROM unnest(NEW.allowed_email_domains) x WHERE trim(x) <> '' ORDER BY 1
    );
    IF cardinality(NEW.allowed_email_domains) = 0 THEN
      NEW.allowed_email_domains := NULL;
    END IF;
    FOREACH d IN ARRAY coalesce(NEW.allowed_email_domains, '{}') LOOP
      IF d !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' THEN
        RAISE EXCEPTION 'not an email domain: %', d USING ERRCODE = 'check_violation';
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER email_domains BEFORE INSERT OR UPDATE OF allowed_email_domains ON organizations
  FOR EACH ROW EXECUTE FUNCTION normalise_email_domains();
--> statement-breakpoint
-- Erased accounts (app_erase_user) use a reserved domain that no list holds.
CREATE FUNCTION app_email_ok(org uuid, email text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT email LIKE '%@erased.invalid'
    OR coalesce((SELECT o.allowed_email_domains IS NULL OR lower(split_part(email, '@', 2)) = ANY (o.allowed_email_domains)
                 FROM organizations o WHERE o.id = org), true)
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app_email_ok(uuid, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_email_ok(uuid, text) TO selah_app;
--> statement-breakpoint
-- Checked whenever someone joins an organisation and whenever an address changes.
CREATE FUNCTION check_user_email() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE org uuid := app_user_org(NEW.id);
BEGIN
  IF NEW.email IS DISTINCT FROM OLD.email AND org IS NOT NULL AND NOT app_email_ok(org, NEW.email) THEN
    RAISE EXCEPTION 'that address is not on the organisation''s email domains' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER user_email BEFORE UPDATE OF email ON "user" FOR EACH ROW EXECUTE FUNCTION check_user_email();
