-- Erasure (app_erase_user) replaces the name and address; the other-language name goes too.
CREATE FUNCTION erase_name_alt() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.email LIKE 'erased-%@erased.invalid' THEN
    NEW.name_alt := NULL;
  END IF;
  RETURN NEW;
END $$;
