-- ---------------------------------------------------------- companies

-- At most 6 short names of 2 to 100 characters, set by the firm admin only.
CREATE FUNCTION check_short_names() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.short_names IS DISTINCT FROM OLD.short_names AND app_uid() IS NOT NULL AND app_role() IS DISTINCT FROM 'firm_admin' THEN
    RAISE EXCEPTION 'only the firm admin changes short names' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF cardinality(NEW.short_names) > 6
     OR EXISTS (SELECT 1 FROM unnest(NEW.short_names) s WHERE length(btrim(s)) NOT BETWEEN 2 AND 100) THEN
    RAISE EXCEPTION 'up to 6 short names of 2 to 100 characters' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER short_names BEFORE UPDATE OF short_names ON organizations FOR EACH ROW EXECUTE FUNCTION check_short_names();
--> statement-breakpoint
CREATE FUNCTION app_mask_terms(pid uuid) RETURNS TABLE (kind text, term text, entity text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  WITH p AS (
    SELECT org_id, firm_org_id FROM projects
    WHERE id = pid AND (session_user <> 'selah_app' OR app_can_see_project(pid))
  ), orgs AS (
    SELECT o.id, o.name, o.name_ar, o.display_alias, o.short_names FROM organizations o, p WHERE o.id IN (p.org_id, p.firm_org_id)
    UNION
    SELECT o.id, o.name, o.name_ar, o.display_alias, o.short_names FROM organizations o, p
    WHERE o.kind = 'client'
      AND (session_user <> 'selah_app' OR app_org() = p.firm_org_id)
      AND EXISTS (SELECT 1 FROM projects x WHERE x.org_id = o.id AND x.firm_org_id = p.firm_org_id)
  ), terms AS (
    SELECT 'ORG' AS kind, unnest(ARRAY[o.name, o.name_ar, o.display_alias] || o.short_names) AS term, 'org:' || o.id AS entity
      FROM orgs o
    UNION
    SELECT 'PERSON', unnest(ARRAY[u.name, u.name_alt]), 'user:' || u.id FROM "user" u JOIN org_memberships m ON m.user_id = u.id, p
      WHERE m.org_id IN (p.org_id, p.firm_org_id)
    UNION
    SELECT 'PERSON', unnest(ARRAY[c.name, c.name_alt]), 'contact:' || c.id FROM client_contacts c, p WHERE c.org_id = p.org_id
    UNION
    SELECT 'DEPT', unnest(ARRAY[d.name_ar, d.name_en]), 'dept:' || d.id FROM departments d, p WHERE d.org_id = p.org_id
    UNION
    -- Client people with no account, named as an action's owner ("ماجد الواحي (مدير المكتب)"): the name without the role.
    SELECT 'PERSON', n, 'owner:' || md5(n) FROM (
      SELECT DISTINCT btrim(regexp_replace(a.owner_name, '\s*\(.*\)\s*$', '')) AS n FROM actions a WHERE a.project_id = pid AND a.owner_name IS NOT NULL
    ) o
  )
  SELECT DISTINCT kind, btrim(term), entity FROM terms WHERE term IS NOT NULL AND length(btrim(term)) >= 2
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app_mask_terms(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_mask_terms(uuid) TO selah_app;
--> statement-breakpoint

-- ==========================================================================
-- Action mail (was migration 0051)
-- ==========================================================================
-- Mail for action events (bug register 17, approved 2026-10-22). An action
-- owner who doesn't open Selah still hears they have work: when an action is
-- released or handed to them, sent back for revision, verified, or given a
-- new item of evidence to send.
--
-- The mail follows the in-app notification, so every path that tells the
-- owner in the app (src/services/actions.ts, plan.ts, follow-through.ts) also
-- mails them, and nothing else can. The app role may insert notifications for
-- anyone it can see, so the trigger mails only when the notification matches
-- the action as it stands (the person is its owner, and it really is in that
-- state), only to someone still active, and at most once an hour per person,
-- action and event (mailed_at marks the notification that sent one, so an
-- early notice that mailed nothing never holds back the real one). Like
-- every Selah mail it carries a line and a link, never the action's title
-- or content.

ALTER TABLE outbound_emails ADD CONSTRAINT outbound_kind CHECK (kind IN (
  'invitation', 'email_change.confirm', 'email_change.notice', 'access_review.due',
  'meeting.invite', 'meeting.cancel', 'password_reset', 'password_reset.notice', 'two_factor.reset',
  'inquiry.new', 'action.assigned', 'action.revision_requested', 'action.verified_complete', 'evidence.requested'));
--> statement-breakpoint
CREATE FUNCTION mail_action_notification() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE a record; addr text; matches boolean;
BEGIN
  NEW.mailed_at := NULL;
  IF NEW.entity_type <> 'action'
     OR NEW.kind NOT IN ('action.assigned', 'action.revision_requested', 'action.verified_complete', 'evidence.requested') THEN
    RETURN NEW;
  END IF;
  SELECT x.owner_user_id, x.status INTO a FROM actions x WHERE x.id = NEW.entity_id;
  IF NOT FOUND OR a.owner_user_id IS DISTINCT FROM NEW.user_id THEN
    RETURN NEW;
  END IF;
  matches := CASE NEW.kind
    -- Released to them, or handed to them while it's under way.
    WHEN 'action.assigned' THEN a.status NOT IN ('draft', 'verified_complete', 'closed')
    WHEN 'action.revision_requested' THEN a.status = 'revision_requested'
    WHEN 'action.verified_complete' THEN a.status = 'verified_complete'
    ELSE a.status NOT IN ('draft', 'verified_complete', 'closed')
      AND EXISTS (SELECT 1 FROM evidence_requests r WHERE r.action_id = NEW.entity_id AND r.status = 'open')
  END;
  IF NOT matches THEN
    RETURN NEW;
  END IF;
  IF NOT app_can_reset_password(NEW.user_id) THEN
    RETURN NEW; -- switched off or erased: no mail
  END IF;
  IF EXISTS (
    SELECT 1 FROM notifications n
    WHERE n.user_id = NEW.user_id AND n.kind = NEW.kind AND n.entity_id = NEW.entity_id
      AND n.mailed_at > now() - interval '1 hour'
  ) THEN
    RETURN NEW;
  END IF;
  SELECT u.email INTO addr FROM "user" u WHERE u.id = NEW.user_id;
  IF addr IS NOT NULL THEN
    INSERT INTO outbound_emails (to_email, kind, link) VALUES (addr, NEW.kind, '/actions/' || NEW.entity_id);
    NEW.mailed_at := now();
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION mail_action_notification() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER mail_action_notification BEFORE INSERT ON notifications
  FOR EACH ROW EXECUTE FUNCTION mail_action_notification();
--> statement-breakpoint

-- ==========================================================================
-- Record passages (was migration 0052)
-- ==========================================================================

CREATE POLICY with_source ON ai_chunks AS RESTRICTIVE FOR SELECT TO selah_app
  USING (CASE source_type
    WHEN 'document' THEN EXISTS (SELECT 1 FROM documents d WHERE d.id = source_id AND d.ai_indexable AND d.state <> 'archived')
    WHEN 'recommendation' THEN EXISTS (SELECT 1 FROM recommendations r WHERE r.id = source_id)
    WHEN 'action' THEN EXISTS (SELECT 1 FROM actions a WHERE a.id = source_id)
    ELSE true
  END);
--> statement-breakpoint
-- A record's passage goes when its text, its label or the record goes; the
-- job writes it again from the record as it now stands. An action's passage
-- carries its recommendation's title and label, so a change there drops the
-- actions' passages too. (A move to another department is handled in the engagement section.)
CREATE FUNCTION drop_record_chunks() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Saving a form writes every field; only a real change drops the passage.
    IF TG_TABLE_NAME = 'recommendations' THEN
      IF (NEW.title, NEW.rationale, NEW.target_outcome, NEW.required_evidence, NEW.visibility)
         IS NOT DISTINCT FROM (OLD.title, OLD.rationale, OLD.target_outcome, OLD.required_evidence, OLD.visibility) THEN
        RETURN NULL;
      END IF;
    ELSIF (NEW.title, NEW.description, NEW.recommendation_id) IS NOT DISTINCT FROM (OLD.title, OLD.description, OLD.recommendation_id) THEN
      RETURN NULL;
    END IF;
  END IF;
  IF TG_TABLE_NAME = 'recommendations' THEN
    DELETE FROM ai_chunks WHERE (source_type = 'recommendation' AND source_id = OLD.id)
      OR (source_type = 'action' AND source_id IN (SELECT a.id FROM actions a WHERE a.recommendation_id = OLD.id));
  ELSE
    DELETE FROM ai_chunks WHERE source_type = 'action' AND source_id = OLD.id;
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION drop_record_chunks() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER record_chunks AFTER UPDATE OF title, rationale, target_outcome, required_evidence, visibility ON recommendations
  FOR EACH ROW EXECUTE FUNCTION drop_record_chunks();
--> statement-breakpoint
CREATE TRIGGER record_chunks_gone AFTER DELETE ON recommendations
  FOR EACH ROW EXECUTE FUNCTION drop_record_chunks();
--> statement-breakpoint
CREATE TRIGGER record_chunks AFTER UPDATE OF title, description, recommendation_id ON actions
  FOR EACH ROW EXECUTE FUNCTION drop_record_chunks();
--> statement-breakpoint
CREATE TRIGGER record_chunks_gone AFTER DELETE ON actions
  FOR EACH ROW EXECUTE FUNCTION drop_record_chunks();
